  'guide.sc.r7.act': 'Open Command Palette / Unified Settings / Floating Mini-Player',
  'guide.sc.r8.act': 'Play/Pause (outside text inputs), Previous/Next track, Seek -10s / +10s',
  'guide.sc.r9.act': 'Volume +5% / -5% / Toggle Mute',
